function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function out($title,$body,$status=200){http_response_code($status);echo '<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.h($title).'</title><style>body{margin:0;min-height:100vh;display:grid;place-items:center;padding:1rem;background:#0a0908;color:#f4f1ea;font-family:tahoma}.c{width:min(100%,500px);padding:2rem;border:1px solid #3c3327;border-radius:22px;background:#151413}p{color:#b6afa7;line-height:2}.n{padding:.8rem;background:#202d22;color:#c7f4cf;border-radius:10px}.e{padding:.8rem;background:#3b1c20;color:#ffc4ca;border-radius:10px}a{display:inline-block;margin-top:1rem;padding:.7rem 1rem;border-radius:10px;background:#c8a862;color:#0a0908;text-decoration:none;font-weight:bold}</style><main class="c">'.$body.'</main></html>';exit;}
