try{$pdo=new PDO('mysql:host='.MH_DB_HOST.';dbname='.MH_DB_NAME.';charset=utf8mb4',MH_DB_USER,MH_DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$sql=preg_replace('/^\s*--.*$/m','',file_get_contents(__DIR__.'/schema.sql'));foreach(preg_split('/;\s*(?:\r?\n|$)/',$sql,-1,PREG_SPLIT_NO_EMPTY) as $q)if(trim($q))$pdo->exec(trim($q));$check=$pdo->query("SELECT COUNT(*) FROM client_demo_items")->fetchColumn();if(!$check){$s=$pdo->prepare('INSERT INTO client_demo_items(site_type,title,subtitle,image,price,status,created_at) VALUES(?,?,?,?,?,?,UTC_TIMESTAMP())');foreach([['studio','Skyline Residence','طراحی داخلی مسکونی','architecture-hero.jpg',0,'active'],['estate','Villa No. 04','فایل ویلایی منتخب','estate-hero.jpg',18500000000,'active'],['clinic','Signature Skin Plan','پکیج مراقبت پوست','clinic-hero.jpg',0,'active']] as $i)$s->execute($i);}file_put_contents(LOCK,date('c'));out('آپدیت موفق','<h1>صفحه‌های مشتری و داشبوردها فعال شدند</h1><p class="n">Studio، Estate و Clinic همراه با داشبورد اختصاصی آماده‌اند.</p><a href="../">صفحه اصلی</a>');}catch(Throwable $e){out('خطا', '<p class="e">'.h($e->getMessage()).'</p>',500);}
